Given the heads of two sorted linked lists, merge them into a single sorted linked list and return the head of the merged list.Examples:Input:  Output: 2 -> 3 -> 5 -> 10 -> 15 -> 20 -> 40Explanation: Merging two sorted lists [5, 10, 15, 40] and [2, 3, 20] in order gives 2 -> 3 -> 5 -> 10 -> 15 -> 20 -> 40. Input: Output: 1 -> 1 -> 2 -> 4 Explanation: Merging [1 ,1] and [2, 4] in order gives 1 -> 1 -> 2 -> 4. Try It YourselfTable of Content[Naive Approach] By Using Array - O((n+m) × log(n+m)) Time and O(n+m) Space[Better Approach] Using Recursive Merge - O(n+m) Time and O(n+m) Space[Efficient Approach] Using Iterative Merge - O(n+m) Time and O(1) Space[Naive Approach] By Using Array - O((n+m) × log(n+m)) Time and O(n+m) SpaceThe idea is to use an array to store all the node data from both linked lists, sort the array, and then construct the resultant sorted linked list from the array elements.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class Node {
  public:
    int data;
    Node *next;

    Node(int x) {
        data = x;
        next = nullptr;
    }
};

Node *sortedMerge(Node *head1, Node *head2) {
    vector<int> arr;

    // pushing the values of the first linked list
    while (head1 != nullptr) {
        arr.push_back(head1->data);
        head1 = head1->next;
    }

    // pushing the values of the second linked list
    while (head2 != nullptr) {
        arr.push_back(head2->data);
        head2 = head2->next;
    }

    // sorting the vector
    sort(arr.begin(), arr.end());

    // creating a new list with sorted values
    Node *dummy = new Node(-1);
    Node *curr = dummy;

    for (int i = 0; i < arr.size(); i++) {
        curr->next = new Node(arr[i]);
        curr = curr->next;
    }

    return dummy->next;
}

void printList(Node *curr) {
    while (curr != nullptr) {
        cout << curr->data;
        if (curr->next != nullptr)
            cout << " -> ";
        curr = curr->next;
    }
    cout << endl;
}

int main() {

    Node *head1 = new Node(5);
    head1->next = new Node(10);
    head1->next->next = new Node(15);
    head1->next->next->next = new Node(40);

    Node *head2 = new Node(2);
    head2->next = new Node(3);
    head2->next->next = new Node(20);

    Node *res = sortedMerge(head1, head2);

    printList(res);

    return 0;
}


